+			
+				// check base
+				if(ie instanceof InstanceInvokeExpr)
+				{
+					InstanceInvokeExpr iie = (InstanceInvokeExpr) ie;
+					if(mloa.isObjectLocal(iie.getBase()))
+						callingContext.setAllFieldsLocal();
+					else
+						callingContext.setAllFieldsShared();
+				}
+				else
+				{
+					callingContext.setAllFieldsShared();
+				}
